using System;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;
namespace Lab06_CSDL_Basic{
public class CuaHangForm:Form{
public CuaHangForm(){Text="QLCuaHang";StartPosition=FormStartPosition.CenterParent;ClientSize=new Size(500,280);Controls.Add(new Label{Text="QUẢN LÝ CỬA HÀNG",Left=70,Top=20,Width=360,Height=40,Font=new Font("Segoe UI",16,FontStyle.Bold),TextAlign=ContentAlignment.MiddleCenter});Add("Tạo tồn kho ngày hiện tại",70,TaoTon);Add("Thêm sản phẩm mới",120,ThemSP);Add("Bán hàng / tạo hóa đơn",170,BanHang);}
void Add(string t,int y,Action a){var b=new Button{Text=t,Left=90,Top=y,Width=320,Height=35};b.Click+=(s,e)=>{try{a();}catch(Exception x){MessageBox.Show(x.Message);}};Controls.Add(b);}
void TaoTon(){int n=Db.Execute(@"INSERT INTO QLCuaHang.dbo.TONKHO(MaSP,NgayTon,SLDau,SLNhap,SLBan)
SELECT s.MaSP,CONVERT(date,GETDATE()),ISNULL(p.SLDau+p.SLNhap-p.SLBan,0),0,0 FROM QLCuaHang.dbo.SANPHAM s
OUTER APPLY(SELECT TOP 1 SLDau,SLNhap,SLBan FROM QLCuaHang.dbo.TONKHO t WHERE t.MaSP=s.MaSP AND t.NgayTon<CONVERT(date,GETDATE()) ORDER BY NgayTon DESC)p
WHERE NOT EXISTS(SELECT 1 FROM QLCuaHang.dbo.TONKHO t WHERE t.MaSP=s.MaSP AND t.NgayTon=CONVERT(date,GETDATE()))");MessageBox.Show("Đã tạo tồn kho cho "+n+" sản phẩm.");}
void ThemSP(){using(var f=new Form{Text="Thêm sản phẩm",Size=new Size(360,160),StartPosition=FormStartPosition.CenterParent}){var t=new TextBox{Left=100,Top=20,Width=220};var b=new Button{Text="Lưu",Left=100,Top=60,Width=90};f.Controls.Add(new Label{Text="Tên SP",Left=15,Top=23});f.Controls.Add(t);f.Controls.Add(b);b.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(t.Text)){MessageBox.Show("Nhập tên sản phẩm.");return;}using(var c=Db.OpenConnection())using(var tr=c.BeginTransaction())try{int id;using(var q=new SqlCommand("INSERT INTO QLCuaHang.dbo.SANPHAM(TenSP) OUTPUT INSERTED.MaSP VALUES(@t)",c,tr)){q.Parameters.Add("@t",SqlDbType.NVarChar,120).Value=t.Text.Trim();id=Convert.ToInt32(q.ExecuteScalar());}using(var q=new SqlCommand("INSERT INTO QLCuaHang.dbo.TONKHO(MaSP,NgayTon,SLDau,SLNhap,SLBan) VALUES(@id,CONVERT(date,GETDATE()),0,0,0)",c,tr)){q.Parameters.Add("@id",SqlDbType.Int).Value=id;q.ExecuteNonQuery();}tr.Commit();MessageBox.Show("Đã thêm sản phẩm và tồn kho đầu ngày.");f.Close();}catch(Exception x){tr.Rollback();MessageBox.Show(x.Message);}};f.ShowDialog(this);}}
void BanHang(){using(var f=new Form{Text="Bán hàng",Size=new Size(440,280),StartPosition=FormStartPosition.CenterParent}){var inv=new TextBox{Left=125,Top=20,Width=270,ReadOnly=true};var sp=new ComboBox{Left=125,Top=60,Width=270,DropDownStyle=ComboBoxStyle.DropDownList};var sl=new TextBox{Left=125,Top=100,Width=270};var msg=new Label{Left=20,Top=145,Width=380};f.Controls.Add(new Label{Text="Mã hóa đơn",Left=20,Top=23});f.Controls.Add(inv);f.Controls.Add(new Label{Text="Sản phẩm",Left=20,Top=63});f.Controls.Add(sp);f.Controls.Add(new Label{Text="Số lượng",Left=20,Top=103});f.Controls.Add(sl);f.Controls.Add(msg);foreach(DataRow r in Db.Query("SELECT MaSP,TenSP FROM QLCuaHang.dbo.SANPHAM").Rows)sp.Items.Add(new PItem(Convert.ToInt32(r[0]),r[1].ToString()));
int hd=0;var create=new Button{Text="Tạo hóa đơn",Left=20,Top=185,Width=115};var add=new Button{Text="Thêm chi tiết",Left=150,Top=185,Width=115};var pay=new Button{Text="Thanh toán",Left=280,Top=185,Width=115};add.Enabled=false;pay.Enabled=false;f.Controls.Add(create);f.Controls.Add(add);f.Controls.Add(pay);
create.Click+=(s,e)=>{using(var c=Db.OpenConnection())using(var q=new SqlCommand("INSERT INTO QLCuaHang.dbo.HOADON(NgayTao,TinhTrangThanhToan) OUTPUT INSERTED.MaHD VALUES(CONVERT(date,GETDATE()),0)",c)){hd=Convert.ToInt32(q.ExecuteScalar());inv.Text=hd.ToString();}add.Enabled=true;pay.Enabled=true;msg.Text="Hóa đơn chưa thanh toán.";};
add.Click+=(s,e)=>{int qty;if(hd==0||sp.SelectedItem==null||!int.TryParse(sl.Text,out qty)||qty<=0){MessageBox.Show("Chọn sản phẩm và nhập số lượng nguyên dương.");return;}var p=(PItem)sp.SelectedItem;using(var c=Db.OpenConnection())using(var tr=c.BeginTransaction())try{object val;using(var q=new SqlCommand("SELECT TOP 1 SLDau+SLNhap-SLBan FROM QLCuaHang.dbo.TONKHO WITH(UPDLOCK,HOLDLOCK) WHERE MaSP=@p AND NgayTon=CONVERT(date,GETDATE())",c,tr)){q.Parameters.Add("@p",SqlDbType.Int).Value=p.Id;val=q.ExecuteScalar();}if(val==null||val==DBNull.Value)throw new Exception("Chưa tạo tồn kho hôm nay.");int avail=Convert.ToInt32(val);if(qty>=avail)throw new Exception("Theo đề bài, số lượng bán phải nhỏ hơn tồn kho ("+avail+").");using(var q=new SqlCommand("INSERT INTO QLCuaHang.dbo.CHITIET_HOADON(MaHD,MaSP,SoLuong) VALUES(@h,@p,@q)",c,tr)){q.Parameters.Add("@h",SqlDbType.Int).Value=hd;q.Parameters.Add("@p",SqlDbType.Int).Value=p.Id;q.Parameters.Add("@q",SqlDbType.Int).Value=qty;q.ExecuteNonQuery();}using(var q=new SqlCommand("UPDATE QLCuaHang.dbo.TONKHO SET SLBan=SLBan+@q WHERE MaSP=@p AND NgayTon=CONVERT(date,GETDATE())",c,tr)){q.Parameters.Add("@q",SqlDbType.Int).Value=qty;q.Parameters.Add("@p",SqlDbType.Int).Value=p.Id;q.ExecuteNonQuery();}tr.Commit();msg.Text="Đã thêm chi tiết hóa đơn."; }catch(Exception x){tr.Rollback();MessageBox.Show(x.Message);}};
pay.Click+=(s,e)=>{if(hd>0){Db.Execute("UPDATE QLCuaHang.dbo.HOADON SET TinhTrangThanhToan=1 WHERE MaHD=@h",Db.P("@h",SqlDbType.Int,hd));msg.Text="Đã thanh toán.";add.Enabled=false;pay.Enabled=false;}};f.ShowDialog(this);}}
class PItem{public int Id;string N;public PItem(int i,string n){Id=i;N=n;}public override string ToString(){return Id+" - "+N;}}
}}
